def circular_shift(x, shift):
    s = str(x)
    n = len(s)
    if abs(shift) > n:
        return s[::-1]
    shift %= n
    if shift == 0:
        return s
    # positive shift: right shift; negative shift: left shift
    return s[-shift:] + s[:-shift]


