def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)

    def is_non_decreasing(a):
        return all(a[i] <= a[i+1] for i in range(len(a)-1))

    def is_non_increasing(a):
        return all(a[i] >= a[i+1] for i in range(len(a)-1))

    # Try all right shifts from 0 to n-1
    for shift in range(n):
        # Right shift by 'shift' means last 'shift' elements move to front
        shifted = arr[-shift:] + arr[:-shift] if shift > 0 else arr
        if is_non_decreasing(shifted) or is_non_increasing(shifted):
            return True

    return False


