def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input: string of space-separated valid parentheses groups.
    Output: list of integers representing the maximum nesting depth of each group.
    """
    groups = paren_string.split()
    # For each group, track current depth and max depth using map and sum.
    # No loops or recursion explicitly used.
    def max_depth(group: str) -> int:
        # Use accumulate from itertools to track running depth
        from itertools import accumulate
        depths = accumulate((1 if c == '(' else -1 for c in group))
        # max depth is max of partial sums
        return max(depths)
    return list(map(max_depth, groups))


