from typing import List, Tuple

def parse_music(music_string: str) -> Tuple[List[int], str]:
    beats_map = {'o': 4, 'o|': 2, '.|': 1}
    if not music_string.strip():
        return [], ''
    notes = music_string.split()

    beats_list = list(map(lambda n: beats_map[n], notes))

    count_o = notes.count('o')
    count_o_bar = notes.count('o|')
    count_dot_bar = notes.count('.|')

    counts = {'o': count_o, 'o|': count_o_bar, '.|': count_dot_bar}
    max_count = max(counts.values())

    candidates = [k for k, v in counts.items() if v == max_count]

    most_common_note = max(candidates, key=lambda n: beats_map[n])

    return beats_list, most_common_note


