def triples_sum_to_zero(l):
    nums = list(map(int, l))
    n = len(nums)
    if n < 3:
        return False

    sorted_nums = sorted(nums)
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            s = sorted_nums[i] + sorted_nums[left] + sorted_nums[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False


