def monotonic(l):
    if isinstance(l, list):
        # For lists: duplicates allowed; check if monotonically increasing or decreasing (non-strict),
        # return (True, sum) or False if not monotonic.
        # No loops or sorting.

        def is_non_decreasing(i=0):
            if i >= len(l) - 1:
                return True
            if l[i] > l[i + 1]:
                return False
            return is_non_decreasing(i + 1)

        def is_non_increasing(i=0):
            if i >= len(l) - 1:
                return True
            if l[i] < l[i + 1]:
                return False
            return is_non_increasing(i + 1)

        if is_non_decreasing() or is_non_increasing():
            return True, sum(l)
        else:
            return False

    elif isinstance(l, str):
        # For strings: no duplicates allowed, check if strictly increasing or strictly decreasing by character order,
        # return (True, string) or False if duplicates or not monotonic
        # No loops or sorting.

        # Check duplicates
        if len(set(l)) != len(l):
            return False

        def strictly_increasing(i=0):
            if i >= len(l) - 1:
                return True
            if l[i] >= l[i + 1]:
                return False
            return strictly_increasing(i + 1)

        def strictly_decreasing(i=0):
            if i >= len(l) - 1:
                return True
            if l[i] <= l[i + 1]:
                return False
            return strictly_decreasing(i + 1)

        if strictly_increasing() or strictly_decreasing():
            return True, l
        else:
            return False

    else:
        # If input is neither list nor str, return False
        return False


