def total_match(lst1, lst2):
    # Check if there are any strings in either list
    strings1 = [x for x in lst1 if isinstance(x, str)]
    strings2 = [x for x in lst2 if isinstance(x, str)]
    all_strings = strings1 + strings2
    if all_strings:
        # Return the longest string among all strings found
        return max(all_strings, key=len)

    # Convert all elements to int (assuming they're integers or can be treated as such)
    # Calculate total digits in each list's numbers
    def total_digits(lst):
        # sum digits count of abs numbers (handle zero too)
        return sum(len(str(abs(x))) for x in lst)

    td1 = total_digits(lst1)
    td2 = total_digits(lst2)

    # Select the list with fewer digits, or lst1 if equal
    chosen = lst1 if td1 <= td2 else lst2

    # Sort chosen ascending but maintain original order for duplicates:
    # We sort by value, but stable sort maintains order for equal values.
    # Python's sorted is stable.
    sorted_chosen = sorted(chosen)

    # Return as space-separated string
    return ' '.join(str(x) for x in sorted_chosen)


