def maximum(arr, k):
    if k == 0:
        return []

    # Find the k largest elements in arr using a simple selection approach (no built-in sort)
    # Since time complexity O(1) is impossible for this task realistically,
    # we follow the instructions and implement a straightforward approach.

    # Copy arr so we don't modify original
    arr_copy = arr[:]
    max_elements = []

    for _ in range(k):
        # Find the max element in arr_copy
        max_val = arr_copy[0]
        max_idx = 0
        for i in range(1, len(arr_copy)):
            if arr_copy[i] > max_val:
                max_val = arr_copy[i]
                max_idx = i
        max_elements.append(max_val)
        # Remove this max element from arr_copy to find next max
        arr_copy.pop(max_idx)

    # Now max_elements contains k largest elements (unsorted)
    # We must return them sorted ascending without using built-in sort

    # Implement insertion sort on max_elements
    for i in range(1, len(max_elements)):
        key = max_elements[i]
        j = i - 1
        while j >= 0 and max_elements[j] > key:
            max_elements[j + 1] = max_elements[j]
            j -= 1
        max_elements[j + 1] = key

    return max_elements


