def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Check if array is already non-decreasing
    if all(arr[i] <= arr[i+1] for i in range(n-1)):
        return True

    # Find the index where the order breaks
    break_points = [i for i in range(n-1) if arr[i] > arr[i+1]]

    # If more than one break point, cannot be sorted by rotation
    if len(break_points) > 1:
        return False

    # If exactly one break point
    idx = break_points[0]
    # After rotation by (n - idx - 1) right shifts, the array should be sorted
    # Check if last element <= first element to ensure non-decreasing order after rotation
    # Actually, after rotation the array will be:
    # arr[idx+1], arr[idx+2], ..., arr[n-1], arr[0], arr[1], ..., arr[idx]
    # We need to verify that arr[n-1] <= arr[0] to ensure non-decreasing order after rotation.
    return arr[-1] <= arr[0]


