def triples_sum_to_zero(items):
    items = list(items)
    items.sort()
    n = len(items)
    for i in range(n - 2):
        if i > 0 and items[i] == items[i - 1]:
            continue
        left, right = i + 1, n - 1
        while left < right:
            s = items[i] + items[left] + items[right]
            if s == 0:
                return True
            elif s < 0:
                left += 1
            else:
                right -= 1
    return False


