def move_one_ball(seq):
    if not seq:
        return True
    n = len(seq)
    # Since values are distinct, the sequence can be sorted by rotation
    # if and only if it is a rotated sorted sequence.
    # Such sequence has at most one place where seq[i] > seq[i+1].
    count_descents = 0
    for i in range(n):
        if seq[i] > seq[(i+1) % n]:
            count_descents += 1
            if count_descents > 1:
                return False
    return True


