def order_by_points(items):
    def score(n):
        s = str(abs(n))
        digits = list(map(int, s))
        if n < 0:
            # negative of first digit, plus sum of remaining digits
            return -digits[0] + sum(digits[1:])
        else:
            return sum(digits)
    return sorted(items, key=score)


