def move_one_ball(arr):
    if not arr:
        return True
    sorted_arr = sorted(arr)
    n = len(arr)
    # Try all possible right shifts of sorted_arr and check if any matches arr
    # Right shift by k means last k elements move to front
    for k in range(n):
        # rotated version after k right shifts
        rotated = sorted_arr[-k:] + sorted_arr[:-k]
        if rotated == arr:
            return True
    return False


