def monotonic(l: list):
    """Return True if list elements are neither strictly increasing nor strictly decreasing.
    Otherwise return False.
    """
    if len(l) < 2:
        return False  # No trend in lists with fewer than 2 elements

    strictly_increasing = all(x < y for x, y in zip(l, l[1:]))
    strictly_decreasing = all(x > y for x, y in zip(l, l[1:]))

    # According to the task's definition, return False if strictly increasing or decreasing,
    # True otherwise
    return not (strictly_increasing or strictly_decreasing)


