import re

def anti_shuffle(s):
    # Split the string into words and spaces, preserving spaces
    parts = re.findall(r'\S+|\s+', s)
    result = []
    for part in parts:
        if part.isspace():
            # If it's space, keep it as is
            result.append(part)
        else:
            # Sort characters in the word by ASCII ascending
            sorted_word = ''.join(sorted(part))
            result.append(sorted_word)
    return ''.join(result)


