from typing import List

def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Parses the input string into groups separated by any characters other than '(' or ')',
    and for each group computes the maximum nesting depth of parentheses.

    Groups are contiguous sequences of '(' and ')' characters only.
    Other characters separate groups.

    Returns a list of max nesting depths per group.
    If a group is unbalanced or invalid, its max depth is 0.
    """
    groups = []
    current_group = []

    for ch in paren_string:
        if ch in '()':
            current_group.append(ch)
        else:
            if current_group:
                groups.append(''.join(current_group))
                current_group = []
    if current_group:
        groups.append(''.join(current_group))

    def max_depth(group: str) -> int:
        depth = 0
        max_depth = 0
        for c in group:
            if c == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif c == ')':
                depth -= 1
                if depth < 0:
                    # Unbalanced, more closing than opening
                    return 0
        return max_depth if depth == 0 else 0  # 0 if unbalanced (more openings)

    return [max_depth(g) for g in groups]


