def circular_shift(x, shift):
    """Circular shift the digits of the integer x, shift the digits left or right by shift
    and return the result as a string.
    Positive shift means shift right, negative shift means shift left.
    Preserves digit count and leading zeros.
    """
    s = str(abs(x))
    n = len(s)
    if n == 0:
        return s
    shift = shift % n  # normalize shift to be within digit length
    # Positive shift means right rotation
    if shift == 0:
        rotated = s
    else:
        rotated = s[-shift:] + s[:-shift]
    return rotated


