def monotonic(l: list):
    """Return True if list elements are monotonically non-decreasing or non-increasing.
    """
    if not l:
        return True
    non_decreasing = all(x <= y for x, y in zip(l, l[1:]))
    non_increasing = all(x >= y for x, y in zip(l, l[1:]))
    return non_decreasing or non_increasing


