def move_one_ball(arr):
    if not arr:
        return True

    n = len(arr)
    # Since the elements are unique, a sorted rotated array can have at most one place
    # where arr[i] > arr[i+1] (considering i+1 mod n).
    # If there is more than one such place, it's impossible to get sorted array by rotation.

    count_breaks = 0
    for i in range(n):
        if arr[i] > arr[(i + 1) % n]:
            count_breaks += 1
            if count_breaks > 1:
                return False
    return True


