def parse_nested_parens(paren_string):
    """ Input to this function is a string. Output the deepest level of nesting of parentheses.
        Raises a ValueError if the parentheses are unbalanced.
    """
    max_depth = 0
    current_depth = 0
    for char in paren_string:
        if char == '(':
            current_depth += 1
            if current_depth > max_depth:
                max_depth = current_depth
        elif char == ')':
            current_depth -= 1
            if current_depth < 0:
                raise ValueError("Unbalanced parentheses: too many closing parens")
    if current_depth != 0:
        raise ValueError("Unbalanced parentheses: too many opening parens")
    return max_depth


