def digits(n):
    """Given an integer n, return the product of the odd digits."""
    product = 1
    found_odd = False
    for digit in str(abs(n)):
        d = int(digit)
        if d % 2 == 1:
            product *= d
            found_odd = True
    return product if found_odd else 0


