import re

def anti_shuffle(data: str) -> str:
    # This pattern splits the string into substrings of whitespace and non-whitespace
    parts = re.findall(r'\s+|\S+', data)
    # For each non-whitespace substring, sort its characters; keep whitespace parts unchanged
    sorted_parts = [
        ''.join(sorted(part)) if not part.isspace() else part
        for part in parts
    ]
    return ''.join(sorted_parts)


