def select_words(s: str, n: int):
    vowels = set("aeiouAEIOU")
    result = []
    length = len(s)
    if length == 0:
        return result

    for start in range(length):
        non_vowel_count = 0
        for end in range(start, length):
            ch = s[end]
            if ch != ' ' and ch not in vowels:
                non_vowel_count += 1
            if non_vowel_count > n:
                break
            if non_vowel_count == n:
                result.append(s[start:end+1])
    return result


