def circular_shift(x, shift):
    s = str(x)
    if s[0] == '-':
        sign = '-'
        digits = s[1:]
    else:
        sign = ''
        digits = s
    n = len(digits)
    if n == 0:
        return s  # just return as is if no digits
    shift_mod = shift % n
    # For negative numbers, circular shift means rotating digits, but sign stays at front.
    # The example circular_shift(-456, 2) → "56-4" means:
    # The digits "456" shifted right by 2 → "564", but the sign '-' is kept at front,
    # and the digit that moves past the sign is placed just before the sign (like "56-4").
    #
    # However, the user's clarification is that the sign is included in string operations,
    # so the negative sign should be treated as part of the rotation.
    #
    # So the string "-456" rotated right by 2 means the last 2 chars "56" move to front,
    # then the rest "-4" follow → "56-4".
    #
    # So to implement this:
    # rotate the entire string s (including sign) right by shift_mod
    # and return the rotated string.
    #
    # For positive numbers, same logic applies (rotate full string).
    #
    shift_mod = shift % len(s)
    if shift_mod == 0:
        return s
    shifted = s[-shift_mod:] + s[:-shift_mod]
    return shifted


