def order_by_points(nums):
    def key(n):
        s = str(abs(n))
        digits = []
        for i, ch in enumerate(s):
            d = int(ch)
            if n < 0 and i == 0:
                d = -d
            digits.append(d)
        return sum(digits)
    return sorted(nums, key=key)


