def anti_shuffle(s):
    def reorder_word(word):
        letters = [c for c in word if c.isalpha()]
        # sort letters descending by ascii
        letters.sort(reverse=True)
        res = []
        letter_idx = 0
        for c in word:
            if c.isalpha():
                res.append(letters[letter_idx])
                letter_idx += 1
            else:
                res.append(c)
        return ''.join(res)

    # split by spaces keeping them
    import re
    parts = re.split(r'(\s+)', s)
    # reorder only the words (non-space parts)
    for i in range(len(parts)):
        if not parts[i].isspace():
            parts[i] = reorder_word(parts[i])
    return ''.join(parts)


