def digits(n):
    digits_str = str(n)
    odd_digits = [int(d) for d in digits_str if int(d) % 2 == 1]
    if not odd_digits:
        # If no odd digits, return 0
        return 0
    if len(odd_digits) == 1:
        # If only one odd digit, return it
        return odd_digits[0]
    # If multiple odd digits, return their product
    product = 1
    for d in odd_digits:
        product *= d
    return product


