def compute_Last_Digit(a: int, b: int) -> int:
    # factorial(b) / factorial(a) = (a+1) * (a+2) * ... * b
    # We need the last digit of the product of integers from a+1 to b.
    product = 1
    for i in range(a + 1, b + 1):
        product *= i
        product %= 10  # keep only the last digit to avoid large numbers
    return product


