def zip_tuples(*tuples):
    if not tuples:
        return []
    first, *rest = tuples
    length = len(first)
    result = []
    for i in range(length):
        zipped = (first[i],)
        for t in rest:
            zipped += (t[i % len(t)],)
        result.append(zipped)
    return result

