def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    def is_all_nines(s):
        return all(ch == '9' for ch in s)

    # If all digits are 9, the next palindrome is 10...01 with length+1 digits
    if is_all_nines(s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left, middle, odd_length):
        if odd_length:
            return left + middle + left[::-1]
        else:
            return left + left[::-1]

    odd_length = (length % 2 != 0)
    if odd_length:
        left = s[:length//2]
        middle = s[length//2]
        right = s[length//2+1:]
    else:
        left = s[:length//2]
        middle = ''
        right = s[length//2:]

    # Construct palindrome by mirroring left to right
    pal = make_palindrome(left, middle, odd_length)
    pal_num = int(pal)

    if pal_num > num:
        return pal_num

    # Need to increment the middle part and then mirror again
    if odd_length:
        # Increment the middle digit and handle carry
        left_middle = left + middle
        incremented = str(int(left_middle) + 1)
        # If increment changes length, it means carry overflow
        if len(incremented) > len(left_middle):
            # e.g. 999 -> after increment 1000, so palindrome length grows
            left = incremented[:-1]
            middle = incremented[-1]
        else:
            left = incremented[:-1]
            middle = incremented[-1]
        return int(make_palindrome(left, middle, True))
    else:
        # Even length: increment the left half and mirror
        incremented = str(int(left) + 1)
        if len(incremented) > len(left):
            # e.g. 99 -> 100, palindrome length grows
            left = incremented
            return int(make_palindrome(left, '', False))
        else:
            left = incremented
            return int(make_palindrome(left, '', False))


