def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'
    x0 *= n // g
    y0 *= n // g

    # a and b divided by gcd
    a_div = a // g
    b_div = b // g

    # We want x = x0 + k*(b/g), y = y0 - k*(a/g)
    # to be non-negative with minimal x >= 0.

    # Solve inequalities for k:
    # x >= 0 => x0 + k*b_div >= 0 => k >= -x0 / b_div
    # y >= 0 => y0 - k*a_div >= 0 => k <= y0 / a_div

    # Because we want minimal non-negative x, pick smallest k >= ceil(-x0/b_div)
    # that also satisfies k <= floor(y0/a_div).

    import math

    k_min = math.ceil(-x0 / b_div) if b_div != 0 else 0
    k_max = math.floor(y0 / a_div) if a_div != 0 else 0

    if k_min > k_max:
        return 'No solution'

    k = k_min
    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        return 'No solution'

    return ('x = ', x, ', y = ', y)


