def get_total_number_of_sequences(m: int, n: int) -> int:
    # dp[i][x]: number of sequences of length i ending with element x
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Base case: sequences of length 1 can start from any element 1..m
    for x in range(1, m + 1):
        dp[1][x] = 1

    for length in range(2, n + 1):
        # To optimize, precompute prefix sums for dp[length-1]
        prefix = [0] * (m + 2)
        for x in range(1, m + 1):
            prefix[x] = prefix[x - 1] + dp[length - 1][x]

        for x in range(1, m + 1):
            # Previous element y must satisfy y <= x/2
            max_prev = x // 2
            if max_prev >= 1:
                dp[length][x] = prefix[max_prev]

    return sum(dp[n][1:]) if n > 0 else 0


