def find_Max(arr, start, end):
    if start == end:
        return arr[start]
    mid = (start + end) // 2
    # If mid element is greater than the next element, mid element is max
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # If mid element is smaller than the previous element, previous element is max
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]
    # If arr[start] >= arr[mid], max must be in left half
    if arr[start] >= arr[mid]:
        return find_Max(arr, start, mid - 1)
    # Else max is in right half
    return find_Max(arr, mid + 1, end)


