def sum_column(data, col_index):
    total = 0
    for row in data:
        if len(row) <= col_index:
            raise IndexError(f"Row too short for column index {col_index}")
        value = row[col_index]
        if not isinstance(value, (int, float)):
            raise TypeError(f"Non-numeric value {value} found at column {col_index}")
        total += value
    return total


