def lucky_num(n):
    numbers = list(range(1, 2 * n * 10, 2))  # start with a large list of odd numbers
    idx = 1
    while len(numbers) < n or idx < len(numbers):
        if idx >= len(numbers):
            break
        step = numbers[idx]
        if step > len(numbers):
            break
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx > n:
            break
    return numbers[:n]


