def dif_Square(n: int) -> bool:
    # n = a^2 - b^2 = (a-b)(a+b)
    # So n can be expressed as difference of squares iff n can be factored into two integers p and q
    # with the same parity (both odd or both even), since a = (p+q)/2, b = (q-p)/2 must be integers.
    # Also, p*q = n and p <= q or vice versa.
    # So we check for any factor pair (p,q) of n if (p+q) and (q-p) are both even.

    # Handle n = 0 separately: 0 = 0^2 - 0^2 so True.
    if n == 0:
        return True

    abs_n = abs(n)
    # Iterate over all factors of abs_n
    for p in range(1, int(abs_n**0.5) + 1):
        if abs_n % p == 0:
            q = abs_n // p
            # Check two pairs (p,q) and (q,p) to cover both factor orders
            for x, y in [(p, q), (q, p)]:
                # For n positive, (a-b)(a+b) = n
                # For n negative, (a-b)(a+b) = n, so one factor negative
                # We'll handle sign by assigning (a-b) = x and (a+b) = y or vice versa with sign adjustments
                # But to simplify: since a = (x+y)/2 and b = (y - x)/2 must be integers,
                # (x+y) and (y - x) must be even.
                if (x + y) % 2 == 0 and (y - x) % 2 == 0:
                    # Now check if x*y == n (with correct sign)
                    if x * y == n:
                        return True
                    # Also check if (-x)*(-y) == n
                    if (-x) * (-y) == n:
                        return True
                    # Or if (x)*(-y) == n or (-x)*(y) == n
                    if x * (-y) == n or (-x) * y == n:
                        return True
    return False


