def next_smallest_palindrome(num: int) -> int:
    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # If num <= 0, there is no positive smaller palindrome
    if num <= 0:
        return -1  # or 0 if you want non-negative

    # Start checking from num-1 downwards
    for candidate in range(num - 1, -1, -1):
        if is_palindrome(candidate):
            return candidate

    return -1  # fallback if none found (should never happen for non-negative inputs)


