def find_solution(a, b, n):
    def extended_gcd(a, b):
        if b == 0:
            return a, 1, 0
        g, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return g, x, y

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'

    # scale the solution
    x0 *= n // g
    y0 *= n // g

    # coefficients for general solution:
    # x = x0 + k * (b // g)
    # y = y0 - k * (a // g)

    # need to find k so that x >= 0 and y >= 0 (non-negative x only required per task)
    # but task says only x must be non-negative; y can be any integer
    # so just find k so that x >= 0

    b_div = b // g
    a_div = a // g

    # find k to make x >= 0
    if b_div == 0:
        # b_div == 0 means b == 0
        # then equation reduces to a*x = n
        # check if x0 >= 0
        if x0 >= 0:
            return ('x = ', x0, ', y = ', y0)
        else:
            return 'No solution'
    else:
        # x = x0 + k*b_div >= 0
        # k >= -x0 / b_div
        # k must be integer, so k_min = ceil(-x0 / b_div)
        from math import ceil, floor

        k_min = ceil(-x0 / b_div)

        # try k = k_min to get minimal non-negative x
        x_candidate = x0 + k_min * b_div
        y_candidate = y0 - k_min * a_div
        if x_candidate >= 0:
            return ('x = ', x_candidate, ', y = ', y_candidate)
        else:
            return 'No solution'


