def get_total_number_of_sequences(n, m):
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(length, start):
        if length == 1:
            return 1 if start <= m else 0
        total = 0
        # next element must be >= 2 * start and <= m
        start_next = 2 * start
        if start_next > m:
            return 0
        for next_val in range(start_next, m + 1):
            total += count_sequences(length - 1, next_val)
        return total

    total_count = 0
    for first in range(1, m + 1):
        total_count += count_sequences(n, first)
    return total_count


