def find_Max(nums):
    if not nums:
        return None
    left, right = 0, len(nums) - 1
    # If array is not rotated (already sorted ascending)
    if nums[left] < nums[right]:
        return nums[right]
    while left < right:
        mid = (left + right) // 2
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid
    # left is now the index of smallest element, largest is just before it
    return nums[left - 1 if left > 0 else len(nums) - 1]


