def str_to_tuple(s):
    # If the string contains separators like commas or spaces, split accordingly
    # Otherwise, treat each character as a separate digit
    import re
    s = s.strip()
    if ',' in s or ' ' in s:
        parts = re.split(r'[,\s]+', s)
        parts = [p for p in parts if p]
        return tuple(int(p) for p in parts)
    else:
        # No separators, treat each character as a digit
        return tuple(int(ch) for ch in s)


