def lucky_num(n):
    # Start with a list of odd numbers starting with 1 (all odd numbers)
    numbers = list(range(1, 2 * n * 10, 2))  # overshoot to ensure enough lucky numbers
    idx = 1  # index of the current step (start with second element)

    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element starting from index step-1 (0-based)
        # Because indexing is zero-based, we remove elements at positions: step-1, 2*step-1, 3*step-1, ...
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n:
            # We can stop early if we have at least n lucky numbers
            pass

    return numbers[:n]


