from math import gcd
from functools import reduce

def get_gcd(arr):
    non_zero = [x for x in arr if x != 0]
    # If all elements are zero, gcd is undefined; 
    # but problem states at least one zero and gcd must be strictly positive,
    # so there must be at least one non-zero element.
    # Still, to be safe, handle empty non_zero:
    if not non_zero:
        raise ValueError("Array must contain at least one non-zero element to compute a strictly positive gcd.")
    return reduce(gcd, non_zero)


