def compute_Last_Digit(a: int, b: int) -> int:
    start = min(a, b) + 1
    end = max(a, b)
    result = 1
    for num in range(start, end + 1):
        result = (result * (num % 10)) % 10
        # If result is 0, no need to continue multiplying as last digit stays 0
        if result == 0:
            break
    return result


