def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares (a^2 - b^2)
    # if and only if n is not congruent to 2 mod 4.
    # Proof:
    # a^2 - b^2 = (a+b)(a-b)
    # Both (a+b) and (a-b) are integers.
    # The difference of squares can represent all integers except those congruent to 2 mod 4.
    return n % 4 != 2


