    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    def make_palindrome(left: str, odd_length: bool) -> int:
        if odd_length:
            return int(left + left[-2::-1])
        else:
            return int(left + left[::-1])

    odd_length = (length % 2 != 0)
    mid = length // 2

    if odd_length:
        left = s[:mid+1]
    else:
        left = s[:mid]

    p = make_palindrome(left, odd_length)
    if p > n:
        return p

    # Increment the left half and form palindrome again
    left_int = int(left)
    left_int += 1
    left = str(left_int)
    # If incrementing left changes length, e.g. 99 -> 100, adjust palindrome accordingly
    if len(left) > len(s[:mid+1] if odd_length else s[:mid]):
        # length increased, so palindrome length increases by 1 or 2
        return int('1' + ('0' * (length - 1)) + '1')

    return make_palindrome(left, odd_length)


