def find_solution(a: int, b: int, n: int):
    # We want to find non-negative integers x, y such that a*x + b*y = n.
    # If no such non-negative solution exists, return None.

    # Handle trivial cases:
    if n < 0:
        return None  # no non-negative solution possible if n < 0

    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None

    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None

    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Extended Euclidean algorithm to find one integer solution to a*x + b*y = gcd(a,b)
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return None  # no integer solutions at all

    # Scale the particular solution to the target n
    x0 *= n // g
    y0 *= n // g

    # The general integer solution is:
    # x = x0 + k*(b/g)
    # y = y0 - k*(a/g)
    # We want to find k such that x >= 0 and y >= 0.

    a_div = a // g
    b_div = b // g

    # Solve inequalities:
    # x0 + k*b_div >= 0 => k >= -x0 / b_div
    # y0 - k*a_div >= 0 => k <= y0 / a_div

    # Note: b_div and a_div can be negative depending on sign of a and b,
    # so we need to handle sign carefully.

    # Let's define bounds for k:
    # Because we want to find integer k satisfying:
    # k >= ceil(-x0 / b_div) if b_div > 0 else k <= floor(-x0 / b_div)
    # k <= floor(y0 / a_div) if a_div > 0 else k >= ceil(y0 / a_div)

    import math

    if b_div > 0:
        k_min = math.ceil(-x0 / b_div)
    else:
        k_min = -math.inf  # no lower bound from x

    if b_div < 0:
        k_max = math.floor(-x0 / b_div)
    else:
        k_max = math.inf  # no upper bound from x

    if a_div > 0:
        k_max2 = math.floor(y0 / a_div)
    else:
        k_max2 = math.inf

    if a_div < 0:
        k_min2 = math.ceil(y0 / a_div)
    else:
        k_min2 = -math.inf

    # Intersect intervals:
    k_lower = max(k_min, k_min2)
    k_upper = min(k_max, k_max2)

    if k_lower > k_upper:
        return None  # no k satisfies constraints => no non-negative solution

    # We want any integer k in [k_lower, k_upper]
    # Let's pick k = k_lower (arbitrary choice)
    k = k_lower

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0 or y < 0:
        # This should not happen if intervals are correct, but just in case
        return None

    return (x, y)


