def get_total_number_of_sequences(m: int, n: int) -> int:
    # Sequences are of length n, elements from 1 to m
    # Consecutive elements must satisfy: next == 2 * current or current == 2 * next
    # Count all such sequences

    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(pos, prev):
        if pos == n:
            return 1
        total = 0
        for next_val in range(1, m + 1):
            if prev is None or next_val == 2 * prev or prev == 2 * next_val:
                total += count_sequences(pos + 1, next_val)
        return total

    # Start with no previous element (prev=None)
    return count_sequences(0, None)


