def dict_depth(d):
    if not isinstance(d, dict):
        return 0
    max_depth = 1
    for v in d.values():
        if isinstance(v, dict):
            max_depth = max(max_depth, 1 + dict_depth(v))
        elif isinstance(v, (list, tuple)):
            for item in v:
                if isinstance(item, dict):
                    max_depth = max(max_depth, 1 + dict_depth(item))
                elif isinstance(item, (list, tuple)):
                    # nested lists/tuples do not increase depth directly,
                    # but might contain dicts deeper
                    # so we check recursively inside these as well
                    def check_nested(obj):
                        nonlocal max_depth
                        if isinstance(obj, dict):
                            max_depth = max(max_depth, 1 + dict_depth(obj))
                        elif isinstance(obj, (list, tuple)):
                            for subitem in obj:
                                check_nested(subitem)
                    check_nested(item)
    return max_depth


