from typing import List

def permute_string(s: str) -> List[str]:
    def backtrack(path, used):
        if len(path) == len(chars):
            result.append("".join(path))
            return
        for i in range(len(chars)):
            if used[i]:
                continue
            # No skipping duplicates here, because duplicates must be included
            used[i] = True
            path.append(chars[i])
            backtrack(path, used)
            path.pop()
            used[i] = False

    chars = sorted(s)
    result = []
    used = [False] * len(chars)
    backtrack([], used)
    return result


