def add_string(lst, fmt):
    # Count the number of substitution slots in fmt
    # Here, we consider '{}' as a substitution slot.
    # To count slots, we use string.Formatter.parse to safely parse the format string.
    from string import Formatter

    formatter = Formatter()
    slots = sum(1 for _, field_name, _, _ in formatter.parse(fmt) if field_name is not None)

    result = []
    if slots == 1:
        for el in lst:
            # format fmt with el converted to string
            formatted = fmt.format(str(el))
            result.append(formatted + str(el))
    else:
        for el in lst:
            # no substitution slot, use fmt as-is
            result.append(fmt + str(el))
    return result


