def find_Max(arr, start, end):
    # If the array is not rotated (sorted ascending), max is the last element
    if arr[start] <= arr[end]:
        return arr[end]

    while start <= end:
        mid = (start + end) // 2

        # Check if mid is the point of rotation (max element)
        if mid < end and arr[mid] > arr[mid + 1]:
            return arr[mid]
        if mid > start and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]

        # Decide which half to search
        if arr[mid] >= arr[start]:
            start = mid + 1
        else:
            end = mid - 1


