import re

def text_match(text):
    # Pattern: 'a' followed by zero or more 'b's, but only if no 'b' follows immediately after.
    # That means matching 'a' followed by zero or more 'b's, but the next character (if any) is not 'b'.
    # Using a negative lookahead after the sequence of bs to ensure no b follows.
    pattern = r'a b* (?!b)'
    # remove spaces for correct regex
    pattern = pattern.replace(" ", "")
    if re.search(pattern, text):
        return 'Found a match!'
    else:
        return 'Not matched!'


