def lucky_num(n):
    # Start with the list of natural numbers from 1 upwards
    numbers = list(range(1, 30000))  # Large enough to find n lucky numbers

    idx = 1
    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from step-1 (0-based index)
        del numbers[step-1::step]
        idx += 1

    return numbers[:n]


