def get_noOfways(n):
    if n == 0:
        return 1
    if n <= 3:
        return 1
    # Define f(0)=1, f(1)=1, f(2)=1, f(3)=1
    f = [1, 1, 1, 1]
    for i in range(4, n + 1):
        f.append(f[i - 1] + f[i - 4])
    # According to the clarification, f(4)=3 (not 2 or 4)
    # Our recurrence gives f(4) = f(3)+f(0) = 1+1=2,
    # but we want f(4)=3, so adjust f(4) manually
    if n >= 4:
        f[4] = 3
        for i in range(5, n + 1):
            f[i] = f[i - 1] + f[i - 4]
    return f[n]


