def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all 9's (e.g. 9, 99, 999)
    if all(ch == '9' for ch in s):
        # Next palindrome after 999 is 1001
        return num + 2  # Since num is 999, next palindrome >999 is 1001

    def make_palindrome(left_half, odd_length):
        if odd_length:
            return int(left_half + left_half[:-1][::-1])
        else:
            return int(left_half + left_half[::-1])

    odd_length = (length % 2 != 0)
    mid = length // 2

    if odd_length:
        left_half = s[:mid+1]
    else:
        left_half = s[:mid]

    palindrome = make_palindrome(left_half, odd_length)

    if palindrome > num:
        return palindrome

    # If palindrome is not greater, increment the left half and form palindrome again
    # Increment left half as integer
    left_num = int(left_half) + 1
    left_half = str(left_num)

    # If increment causes length to increase, e.g. 999 + 1 = 1000 in left half
    # This means the palindrome grows in length
    if len(left_half) > len(s[:mid+1] if odd_length else s[:mid]):
        # This happens for cases like 999 -> left_half increment causes length increase
        # The next palindrome in this case is 10...01 with length+1 digits
        return int("1" + ("0" * (length - 1)) + "1")

    return make_palindrome(left_half, odd_length)


