def find_solution(a, b, n):
    def extended_gcd(x, y):
        if y == 0:
            return (x, 1, 0)
        g, s, t = extended_gcd(y, x % y)
        return (g, t, s - (x // y) * t)

    g, x0, y0 = extended_gcd(a, b)
    if n % g != 0:
        return 'No solution'

    # scale the base solution
    x0 *= n // g
    y0 *= n // g

    # a/g and b/g for parametric solutions
    a_div = a // g
    b_div = b // g

    # We want the smallest non-negative x
    # General solution: x = x0 + k*(b/g), y = y0 - k*(a/g)
    # Find k such that x >= 0 and x is minimal

    # k = ceil(-x0 / (b/g)) to get x >= 0
    # but we want minimal x >= 0, so:
    # k0 = ceil_div(-x0, b_div)

    from math import ceil

    if b_div == 0:
        # If b_div == 0, then b=0, equation is a*x = n
        # solution exists only if n % a == 0
        if n % a != 0:
            return 'No solution'
        x = n // a
        if x < 0:
            return 'No solution'
        y = 0
        return (x, y)

    k = (-x0 + b_div - 1) // b_div  # integer division ceiling for (-x0)/b_div

    x = x0 + k * b_div
    y = y0 - k * a_div

    if x < 0:
        return 'No solution'

    return (x, y)


