def find_Max(arr):
    if not arr:
        return None
    low, high = 0, len(arr) - 1
    # If array is not rotated (sorted ascending), max is last element
    if arr[low] < arr[high]:
        return arr[high]
    while low < high:
        mid = (low + high) // 2
        # If mid element is greater than next element, mid is max
        if mid < high and arr[mid] > arr[mid + 1]:
            return arr[mid]
        # If mid element is smaller than previous element, previous is max
        if mid > low and arr[mid] < arr[mid - 1]:
            return arr[mid - 1]
        # Decide which side to go
        if arr[mid] > arr[low]:
            # max must be to the right
            low = mid + 1
        else:
            # max must be to the left
            high = mid - 1
    return arr[low]


