def substract_elements(t1, t2):
    if isinstance(t1, int) and isinstance(t2, int):
        return t1 - t2
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        if len(t1) != len(t2):
            raise ValueError("Tuples must have the same structure and length")
        return tuple(substract_elements(a, b) for a, b in zip(t1, t2))
    raise TypeError("Both arguments must be integers or tuples of the same structure")


