def lucky_num(n):
    # Start with the list of natural numbers from 1 upwards
    numbers = list(range(1, 2 * n * 10))  # oversize to ensure we get enough lucky numbers
    idx = 1  # start from the second element (index 1)
    while idx < len(numbers) and numbers[idx] <= len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number starting from index step-1
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n:
            continue
        # If too short, extend numbers to ensure enough lucky numbers
        # but this rarely happens with initial oversize
    return numbers[:n]


