def dif_Square(n: int) -> bool:
    # A number n can be expressed as a difference of two squares:
    # n = a^2 - b^2 = (a-b)(a+b)
    # Let x = a-b, y = a+b, then n = x*y with y > x > 0 and both x,y have the same parity
    # because (a+b)+(a-b) = 2a and (a+b)-(a-b) = 2b are both even.
    # So n can be written as difference of squares if and only if n has a factorization
    # into two positive integers x < y such that x and y have the same parity and n = x*y.
    #
    # Also note:
    # - If n is 0, 0 = 0^2 - 0^2, so True.
    # - Negative numbers can also be expressed as difference of squares since a^2 - b^2 can be negative.
    #
    # We'll check all positive divisors x of abs(n), and see if corresponding y = n/x has the same parity.

    if n == 0:
        return True

    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check parity of x and y
            if (x + y) % 2 == 0:
                # Check if x < y (since a > b ≥ 0 implies a+b > a-b > 0)
                # But difference of squares formula works for x <= y as well, since b≥0 means a>b≥0
                # Actually, a = (x+y)//2, b = (y-x)//2 must be integers ≥ 0.
                a = (y + x) // 2
                b = (y - x) // 2
                if a > b >= 0:
                    # Check sign: since n can be negative, difference is a^2 - b^2
                    # Check if a^2 - b^2 == n
                    if a*a - b*b == n:
                        return True
    return False


