def next_smallest_palindrome(n: int) -> int:
    s = str(n + 1)
    length = len(s)

    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If all digits are '9', the next palindrome is 10...01
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    while True:
        if is_palindrome(s):
            return int(s)
        length = len(s)
        half = length // 2
        left = s[:half]
        middle = s[half] if length % 2 else ''
        right = s[half + (1 if length % 2 else 0):]

        # Construct palindrome by mirroring left to right
        if length % 2:
            palindrome = left + middle + left[::-1]
        else:
            palindrome = left + left[::-1]

        if palindrome > s:
            s = palindrome
        else:
            # Need to increment the middle part and propagate carry if needed
            if length % 2:
                # Increment middle digit
                mid_num = int(middle) + 1
                if mid_num < 10:
                    s = left + str(mid_num) + left[::-1]
                else:
                    # middle digit rolled over, increment left part
                    left_num = int(left) + 1
                    left_str = str(left_num)
                    # If length changed due to increment, adjust accordingly
                    if len(left_str) > len(left):
                        # e.g. 999 -> length increased
                        s = left_str + '0' + left_str[:-1][::-1]
                    else:
                        s = left_str + '0' + left_str[::-1]
            else:
                # Even length: increment left part
                left_num = int(left) + 1
                left_str = str(left_num)
                if len(left_str) > len(left):
                    # e.g. 99 -> 100
                    s = left_str + left_str[:-1][::-1]
                else:
                    s = left_str + left_str[::-1]


