def find_solution(a, b, n):
    if b == 0:
        if a == 0:
            return "No solution" if n != 0 else ('x = ', 0, ', y = ', 0)
        if n % a == 0 and n // a >= 0:
            return ('x = ', n // a, ', y = ', 0)
        else:
            return "No solution"
    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return ('x = ', x, ', y = ', y)
        x += 1
    return "No solution"


