        return ''.join(start_char if i % 2 == 0 else other_char for i in range(len(s)))

    pattern0 = build_pattern('0')
    pattern1 = build_pattern('1')

    flips0 = sum(c1 != c2 for c1, c2 in zip(s, pattern0))
    flips1 = sum(c1 != c2 for c1, c2 in zip(s, pattern1))

    # If both flips are equal, choose the pattern starting with '1' (per clarification for '1111' -> '1010')
    if flips1 <= flips0:
        return pattern1
    else:
        return pattern0


