def lucky_num(n):
    # Start with the list of odd numbers starting from 1
    numbers = list(range(1, 2 * n * 10, 2))  # overshoot to ensure enough numbers

    idx = 1
    while len(numbers) < n or idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th number from the list, counting from 1-based index
        del numbers[step - 1::step]
        idx += 1
        if len(numbers) >= n and idx >= len(numbers):
            break

    return numbers[:n]


