def dif_Square(n: int) -> bool:
    # A number n can be expressed as a^2 - b^2 = (a-b)(a+b).
    # So n = x * y where x = a-b, y = a+b.
    # Since a and b are integers, x and y must be integers with the same parity (both odd or both even).
    # Also, y > x > 0 or y > x >= 0 depending on sign of n.
    # Let's consider all factor pairs (x,y) of n and check if (x + y) and (y - x) are even.

    if n == 0:
        # 0 = 0^2 - 0^2
        return True

    abs_n = abs(n)
    for x in range(1, int(abs_n**0.5) + 1):
        if abs_n % x == 0:
            y = abs_n // x
            # Check if x and y have the same parity
            if (x + y) % 2 == 0 and (y - x) % 2 == 0:
                # For n positive, (a+b)(a-b) = n, so sign matches
                # For n negative, the factorization would be negative, so swap sign
                # But since we consider absolute value for factors,
                # just check if the product can be n with suitable signs
                # Actually, since a,b integers, the sign is handled by choosing signs of x,y.
                # So just return True here.
                return True
    return False


