from itertools import cycle

def zip_tuples(*iterables):
    if not iterables:
        return []
    length = len(iterables[0])
    cycled_iterables = [cycle(it) if len(it) < length else iter(it) for it in iterables]
    result = []
    for _ in range(length):
        result.append(tuple(next(it) for it in cycled_iterables))
    return result

