def find_solution(a, b, n):
    if b == 0:
        # If b is 0, equation is a*x = n, so x = n/a if integer and non-negative
        if a != 0 and n % a == 0:
            x = n // a
            if x >= 0:
                return (x, 0)
        return None

    x = 0
    while True:
        remainder = n - a * x
        if remainder < 0:
            # Since x is increasing and remainder is decreasing, no solution beyond this point
            break
        if remainder % b == 0:
            y = remainder // b
            if y >= 0:
                return (x, y)
        x += 1
    return None


