def decode_list(pairs):
    """
    Reconstruct data from a sequence given as a list of pairs [count, value].
    Each pair is a list or tuple of two elements: [count, value].
    Return a list with each value repeated count times.

    Handles cases where value can be any type (including int, str, bool).
    """
    result = []
    for count, value in pairs:
        # Ensure count is an int
        if not isinstance(count, int):
            raise TypeError(f"Count must be int, got {type(count).__name__}")
        result.extend([value] * count)
    return result


