def get_total_number_of_sequences(n: int, k: int) -> int:
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(prev: int, length: int) -> int:
        if length == k:
            return 1
        total = 0
        start = prev * 2 if prev != 0 else 1
        for next_val in range(start, n + 1):
            total += count_sequences(next_val, length + 1)
        return total

    return count_sequences(0, 0)


