def move_num(text: str, numbers: list[int]) -> str:
    """
    Insert numeric values from the list `numbers` into the `text` string
    by replacing each occurrence of '#' with the corresponding number in order.
    If there are more '#' than numbers, leave remaining '#' unchanged.
    If there are more numbers than '#', ignore the extra numbers.
    """
    result = []
    num_iter = iter(numbers)
    for ch in text:
        if ch == '#':
            try:
                result.append(str(next(num_iter)))
            except StopIteration:
                result.append('#')
        else:
            result.append(ch)
    return ''.join(result)


