def str_to_tuple(s: str) -> tuple[int, ...]:
    s = s.strip()
    if not (s.startswith('(') and s.endswith(')')):
        raise ValueError("Input string must start with '(' and end with ')'")
    inner = s[1:-1].strip()
    if not inner:
        return ()
    return tuple(int(x.strip()) for x in inner.split(','))


