def lucky_num(n):
    """
    Generate the first n lucky numbers using the sieve process.
    """
    if n <= 0:
        return []
    # Start with the initial list of odd numbers (all lucky numbers are odd)
    numbers = list(range(1, 2 * n * 10, 2))  # oversize to ensure enough lucky numbers
    idx = 1  # start with the second element (index 1) for sieve step

    while idx < len(numbers):
        step = numbers[idx]
        if step > len(numbers):
            break
        # Remove every step-th element from the current list (1-based counting)
        # Because list is 0-indexed, elements to remove are at indices step-1, 2*step-1, ...
        # But after each removal, indices shift, so better to build a new filtered list
        numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
        idx += 1
        if len(numbers) >= n:
            # Once we have at least n lucky numbers, we can stop the sieve
            # But we should only stop if the current sieve step doesn't affect these first n numbers
            # Actually, it's simpler to just continue as long as idx < len(numbers)
            # But for efficiency, break early if possible
            pass

    return numbers[:n]


