def compute_Last_Digit(a: int, b: int) -> int:
    # The last digit of factorial(b) / factorial(a) is the last digit of the product (a+1)*(a+2)*...*b.
    # If b == a, product is empty, so result is 1.
    if b == a:
        return 1
    product = 1
    for num in range(a + 1, b + 1):
        product = (product * (num % 10)) % 10
        # Once product ends with 0, it will remain 0.
        if product == 0:
            return 0
    return product


