def dif_Square(n: int) -> bool:
    # Any integer n can be represented as a difference of two squares except those congruent to 2 mod 4.
    # Proof outline:
    # a^2 - b^2 = (a+b)(a-b) = n
    # For integer solutions, n must NOT be congruent to 2 mod 4.
    return n % 4 != 2


