def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check if all digits are 9
    if all(ch == '9' for ch in s):
        # Next palindrome greater than 999..9 is 100..001
        return int('1' + ('0' * (length - 1)) + '1')

    # Increment num by 1 because we want strictly greater palindrome
    num += 1
    s = str(num)
    length = len(s)

    while True:
        if s == s[::-1]:
            return int(s)
        # Build palindrome by mirroring left to right
        half = length // 2
        if length % 2 == 0:
            left = s[:half]
            palindrome = left + left[::-1]
        else:
            left = s[:half+1]
            palindrome = left + left[:-1][::-1]

        palindrome_num = int(palindrome)
        if palindrome_num >= num:
            return palindrome_num
        # If palindrome_num < num, increment the middle part and rebuild palindrome
        # Convert left + middle to int and add 1
        if length % 2 == 0:
            left_num = int(left)
            left_num += 1
            left = str(left_num).zfill(half)
            palindrome = left + left[::-1]
        else:
            left_num = int(left)
            left_num += 1
            left = str(left_num).zfill(half+1)
            palindrome = left + left[:-1][::-1]

        s = palindrome
        num = int(s)


