def find_solution(a: int, b: int, n: int):
    if b == 0:
        # equation reduces to a*x = n
        if a == 0:
            return (0, 0) if n == 0 else None
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        return None

    x = 0
    while True:
        diff = n - a * x
        if diff < 0:
            # Since x only increases, no further solutions with nonnegative y possible
            break
        if diff % b == 0:
            y = diff // b
            if y >= 0:
                return (x, y)
        x += 1
    return None


