def lucky_num(n):
    # Generate enough numbers initially; start with a list of odd numbers since lucky numbers start with odds
    # We don't know how large the list should be, so start with a size and increase if needed.
    # The lucky number sieve removes elements at positions given by the lucky numbers themselves.
    # The first lucky number is 1, then 3, then 7, 9, 13, 15, ...
    # The classic sieve:
    # Start with the list of integers from 1 upwards (usually odd numbers)
    # The first number is 1 (always lucky)
    # The second lucky number is 3, so remove every 3rd number from the list (1-based indexing)
    # Next lucky number is the next number in the list after 3, say 7, remove every 7th number, etc.

    # We will generate an initial list big enough to find n lucky numbers.
    # If not enough lucky numbers found, increase and try again.

    # Function to perform the sieve on a list
    def sieve(lst):
        idx = 1  # start from second element (index 1), since first lucky number is at index 0 (value 1)
        while idx < len(lst):
            step = lst[idx]
            if step > len(lst):
                break
            # Remove every step-th element (1-based), so indices are step-1, 2*step-1, ...
            # but since list is zero-indexed, remove indices: step-1, 2*step-1, 3*step-1, ...
            # Removal must be done carefully to avoid messing indices.
            # We can rebuild list excluding these elements.
            new_lst = []
            for i, val in enumerate(lst):
                # i is zero-based index, so position = i+1
                if (i + 1) % step != 0:
                    new_lst.append(val)
            lst = new_lst
            idx += 1
        return lst

    # Start with initial size guess
    size = max(50, n * 10)
    while True:
        # Generate initial list of odd numbers starting from 1
        numbers = list(range(1, size * 2, 2))
        lucky = sieve(numbers)
        if len(lucky) >= n:
            return lucky[:n]
        size *= 2


