def tuple_to_set(*tuples):
    result = set()
    for t in tuples:
        result.update(t)
    return result

def get_noOfways(n: int, m: int) -> int:
    if m != 2:
        return 0
    if n == 0:
        return 1
    if n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0], dp[1] = 1, 1
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]


